package com.superteams.command;

import com.superteams.SuperTeams;
import com.superteams.storage.TeamStore;
import com.superteams.team.*;
import org.bukkit.Bukkit;
import org.bukkit.ChatColor;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public final class TeamCommand implements TabExecutor {
    private final SuperTeams plugin; private final TeamStore store; private final InvitationStore invitations;
    public TeamCommand(SuperTeams plugin,TeamStore store){this.plugin=plugin;this.store=store;this.invitations=new InvitationStore(plugin);}
    private void msg(CommandSender s,String m){s.sendMessage(ChatColor.translateAlternateColorCodes('&',"&b[SuperTeams] &f"+m));}
    private boolean right(Player p,TeamData t,TeamRight r){MemberData m=t.member(p.getUniqueId());return t.owner().equals(p.getUniqueId())||(m!=null&&m.has(r));}
    private boolean validAmount(String raw){try{double n=Double.parseDouble(raw);return Double.isFinite(n)&&n>0&&n<=1000000000;}catch(NumberFormatException ex){return false;}}
    private Object vaultEconomy(){try{Class<?> api=Class.forName("net.milkbowl.vault.economy.Economy");Object reg=Bukkit.getServicesManager().getRegistration(api);return reg==null?null:reg.getClass().getMethod("getProvider").invoke(reg);}catch(ReflectiveOperationException|LinkageError ex){return null;}}
    private boolean economyAction(Player player,double value,boolean take){try{Object eco=vaultEconomy();if(eco==null)return false;Object response=eco.getClass().getMethod(take?"withdrawPlayer":"depositPlayer",org.bukkit.OfflinePlayer.class,double.class).invoke(eco,player,value);return (Boolean)response.getClass().getMethod("transactionSuccess").invoke(response);}catch(ReflectiveOperationException ex){plugin.getLogger().warning("Vault transaction failed: "+ex.getMessage());return false;}}
    @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] a){
        if(a.length==0){if(!(sender instanceof Player p)){msg(sender,"Players only.");return true;}TeamData t=store.byMember(p.getUniqueId());if(t==null){msg(p,"Create a team with /team create <name>.");return true;}plugin.gui().open(p);return true;}
        String sub=a[0].toLowerCase(Locale.ROOT);
        if(sub.equals("create")){if(!(sender instanceof Player p)){msg(sender,"Players only.");return true;}if(!sender.hasPermission("superteams.create")){msg(sender,"No permission.");return true;}if(a.length<2){msg(sender,"Usage: /team create <name>");return true;}String name=a[1];int min=plugin.getConfig().getInt("teams.name-min-length",3),max=plugin.getConfig().getInt("teams.name-max-length",16);if(name.length()<min||name.length()>max||!Pattern.matches(plugin.getConfig().getString("teams.allowed-name-regex","^[A-Za-z0-9_]+$"),name)){msg(p,"Invalid team name.");return true;}if(store.byMember(p.getUniqueId())!=null){msg(p,"You already belong to a team.");return true;}if(!store.create(name,p.getUniqueId(),p.getName())){msg(p,"That team name is already taken.");return true;}msg(p,"Created team "+name+".");return true;}
        if(!(sender instanceof Player p)){msg(sender,"Players only.");return true;}TeamData t=store.byMember(p.getUniqueId());
        switch(sub){
            case "info"->{TeamData target=a.length>1?store.byName(a[1]):t;if(target==null){msg(p,"Team not found.");return true;}msg(p,target.name()+" | members "+target.members().size()+" | friendly fire "+target.friendlyFire());}
            case "transfer"->{if(t==null||!t.owner().equals(p.getUniqueId())){msg(p,"Only the owner can transfer ownership.");return true;}if(a.length<2){msg(p,"Usage: /team transfer <member>");return true;}MemberData next=t.members().values().stream().filter(m->m.lastKnownName().equalsIgnoreCase(a[1])).findFirst().orElse(null);if(next==null||next.uuid().equals(p.getUniqueId())){msg(p,"Member not found.");return true;}t.transferOwner(next.uuid());store.save();msg(p,"Ownership transferred to "+next.lastKnownName()+".");Player online=Bukkit.getPlayer(next.uuid());if(online!=null)msg(online,"You are now the owner of "+t.name()+".");}
            case "disband"->{if(t==null||!t.owner().equals(p.getUniqueId())){msg(p,"Only the owner can disband a team.");return true;}if(a.length<2||!a[1].equalsIgnoreCase("confirm")){msg(p,"This permanently deletes the team. Run /team disband confirm to proceed.");return true;}String name=t.name();if(store.disband(t))msg(p,"Team "+name+" was disbanded.");else msg(p,"Could not disband team.");}
            case "leave"->{if(t==null){msg(p,"You are not in a team.");return true;}if(store.leave(p.getUniqueId()))msg(p,"You left "+t.name()+".");else msg(p,"Owner must transfer ownership or disband the team (not yet implemented).");}
            case "invite"->{if(t==null){msg(p,"You are not in a team.");return true;}if(!right(p,t,TeamRight.INVITE)){msg(p,"Missing INVITE right.");return true;}if(a.length<2){msg(p,"Usage: /team invite <player>");return true;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null){msg(p,"Target must be online.");return true;}if(target.equals(p)||store.byMember(target.getUniqueId())!=null||t.members().size()>=plugin.getConfig().getInt("teams.max-members",10)){msg(p,"Target cannot join this team.");return true;}invitations.put(target.getUniqueId(),t.id(),p.getUniqueId());msg(p,"Invitation sent to "+target.getName()+".");msg(target,p.getName()+" invited you to team "+t.name()+". Use /team accept or /team decline.");}
            case "accept"->{InvitationStore.Invite invite=invitations.get(p.getUniqueId());if(invite==null){msg(p,"You have no pending invitation.");return true;}TeamData target=store.byId(invite.teamId());if(target==null||target.members().size()>=plugin.getConfig().getInt("teams.max-members",10)||store.byMember(p.getUniqueId())!=null){invitations.remove(p.getUniqueId());msg(p,"That invitation is no longer valid.");return true;}if(store.join(target,p.getUniqueId(),p.getName())){invitations.remove(p.getUniqueId());msg(p,"You joined "+target.name()+".");}else msg(p,"Could not join that team.");}
            case "decline"->{if(invitations.remove(p.getUniqueId()))msg(p,"Invitation declined.");else msg(p,"You have no pending invitation.");}
            case "kick"->{if(t==null||a.length<2){msg(p,"Usage: /team kick <player>");return true;}if(!right(p,t,TeamRight.KICK)){msg(p,"Missing KICK right.");return true;}MemberData target=t.members().values().stream().filter(m->m.lastKnownName().equalsIgnoreCase(a[1])).findFirst().orElse(null);if(target==null||target.uuid().equals(p.getUniqueId())){msg(p,"Member not found or invalid target.");return true;}if(store.kick(t,target.uuid())){msg(p,"Removed "+target.lastKnownName()+".");Player online=Bukkit.getPlayer(target.uuid());if(online!=null)msg(online,"You were removed from "+t.name()+".");}else msg(p,"Could not remove that member.");}
            case "rights"->{if(t==null||!right(p,t,TeamRight.MANAGE_MEMBERS)){msg(p,"Missing MANAGE_MEMBERS right or no team.");return true;}if(a.length<4){msg(p,"Usage: /team rights <member> <right> <on|off>");return true;}MemberData m=t.members().values().stream().filter(x->x.lastKnownName().equalsIgnoreCase(a[1])).findFirst().orElse(null);if(m==null||m.uuid().equals(t.owner())){msg(p,"Member not found; owner's rights cannot be edited.");return true;}TeamRight r;try{r=TeamRight.valueOf(a[2].toUpperCase(Locale.ROOT));}catch(IllegalArgumentException ex){msg(p,"Unknown right: "+Arrays.toString(TeamRight.values()));return true;}if(r==TeamRight.MANAGE_MEMBERS&&!t.owner().equals(p.getUniqueId())){msg(p,"Only the owner may delegate MANAGE_MEMBERS.");return true;}if(a[3].equalsIgnoreCase("on"))m.rights().add(r);else if(a[3].equalsIgnoreCase("off"))m.rights().remove(r);else{msg(p,"Use on or off.");return true;}store.save();msg(p,r+" "+(m.has(r)?"granted to ":"revoked from ")+m.lastKnownName()+".");}
            case "bank"->{if(t==null||a.length<2){msg(p,"Usage: /team bank <balance|deposit|withdraw> [amount]");return true;}switch(a[1].toLowerCase(Locale.ROOT)){case "balance"->{if(!right(p,t,TeamRight.BANK_VIEW)){msg(p,"Missing BANK_VIEW right.");return true;}msg(p,"Team bank: "+String.format(Locale.US,"%.2f",t.bankBalance()));}case "deposit"->{if(!right(p,t,TeamRight.BANK_DEPOSIT)){msg(p,"Missing BANK_DEPOSIT right.");return true;}if(a.length<3||!validAmount(a[2])){msg(p,"Enter a positive amount up to 1,000,000,000.");return true;}double n=Double.parseDouble(a[2]);if(vaultEconomy()==null){msg(p,"Vault and an economy plugin are required.");return true;}if(!economyAction(p,n,true)){msg(p,"Deposit failed; check your balance.");return true;}t.bankBalance(t.bankBalance()+n);store.save();msg(p,"Deposited "+n+".");}case "withdraw"->{if(!right(p,t,TeamRight.BANK_WITHDRAW)){msg(p,"Missing BANK_WITHDRAW right.");return true;}if(a.length<3||!validAmount(a[2])){msg(p,"Enter a positive amount up to 1,000,000,000.");return true;}double n=Double.parseDouble(a[2]);if(n>t.bankBalance()){msg(p,"Insufficient team-bank funds.");return true;}if(vaultEconomy()==null){msg(p,"Vault and an economy plugin are required.");return true;}t.bankBalance(t.bankBalance()-n);store.save();if(!economyAction(p,n,false)){t.bankBalance(t.bankBalance()+n);store.save();msg(p,"Withdrawal failed; team balance restored.");return true;}msg(p,"Withdrew "+n+".");}default->msg(p,"Usage: /team bank <balance|deposit|withdraw> [amount]");}}
            case "sethome"->{if(t==null||!right(p,t,TeamRight.HOME_SET)){msg(p,"Missing HOME_SET right or no team.");return true;}org.bukkit.Location l=p.getLocation();t.home(l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());store.save();msg(p,"Team home set.");}
            case "home"->{if(t==null||!right(p,t,TeamRight.HOME_USE)){msg(p,"Missing HOME_USE right or no team.");return true;}if(!t.homeSet()){msg(p,"Your team has no home. Use /team sethome.");return true;}org.bukkit.World w=Bukkit.getWorld(t.homeWorld());if(w==null){msg(p,"The team-home world is unavailable.");return true;}org.bukkit.Location destination=new org.bukkit.Location(w,t.homeX(),t.homeY(),t.homeZ(),t.homeYaw(),t.homePitch());p.teleportAsync(destination).thenAccept(ok->Bukkit.getScheduler().runTask(plugin,()->{if(p.isOnline())msg(p,ok?"Teleported to team home.":"Team-home teleport failed.");}));}
            case "pvp"->{if(t==null||!right(p,t,TeamRight.PVP)){msg(p,"Missing PVP right or no team.");return true;}t.friendlyFire(!t.friendlyFire());store.save();msg(p,"Friendly fire "+(t.friendlyFire()?"enabled":"disabled")+".");}
            case "chat"->{if(t==null||!right(p,t,TeamRight.CHAT)){msg(p,"Missing CHAT right or no team.");return true;}if(a.length<2){msg(p,"Usage: /team chat <message>");return true;}String text=Arrays.stream(a,1,a.length).collect(Collectors.joining(" "));for(MemberData m:t.members().values()){Player receiver=Bukkit.getPlayer(m.uuid());if(receiver!=null&&right(receiver,t,TeamRight.CHAT))msg(receiver,"[Team "+t.name()+"] "+p.getName()+": "+text);}if(plugin.getConfig().getBoolean("chat.spy-enabled",true))for(Player staff:Bukkit.getOnlinePlayers())if(staff.hasPermission("superteams.chatspy")&&t.member(staff.getUniqueId())==null)msg(staff,"[SPY:"+t.name()+"] "+p.getName()+": "+text);return true;}
            default->msg(p,"Commands: create, info, invite, accept, decline, kick, leave, transfer, disband, rights, bank, sethome, home, chat, pvp.");
        }return true;
    }
    @Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1)return List.of("create","invite","accept","decline","kick","leave","transfer","disband","info","chat","pvp","home","sethome","rights","bank","reload").stream().filter(x->x.startsWith(args[0].toLowerCase(Locale.ROOT))).toList();if(args.length==2&&args[0].equalsIgnoreCase("kick")){TeamData t=s instanceof Player p?store.byMember(p.getUniqueId()):null;return t==null?List.of():t.members().values().stream().map(MemberData::lastKnownName).filter(n->n.toLowerCase(Locale.ROOT).startsWith(args[1].toLowerCase(Locale.ROOT))).toList();}return List.of();}
}